const input = $input.first().json;

// 从环境变量读取凭据
const NTFY_URL = $env.NTFY_URL || 'https://ntfy.sh';
const NTFY_USER = $env.NTFY_USER || '';
const NTFY_PASS = $env.NTFY_PASS || '';
const NTFY_TOPIC = $env.NTFY_TOPIC;

// 输入参数（调用方传入）
const title = input.title || 'Hermes 通知';
const body = input.body || input.message || '';
const priority = input.priority || 'default';
const tags = input.tags || [];
const topic = input.topic || NTFY_TOPIC;
const markdown = input.markdown !== false; // 默认启用 markdown

if (!body) {
    return [{ json: { success: false, error: 'body 不能为空' } }];
}

// 构建完整 URL
const url = `${NTFY_URL}/${topic}`;

// 构建 headers
const headers = { 'Content-Type': 'application/json' };
if (NTFY_USER && NTFY_PASS) {
    headers['Authorization'] = 'Basic ' + Buffer.from(`${NTFY_USER}:${NTFY_PASS}`).toString('base64');
}

// 构建 body
const payload = {
    topic,
    message: body,
    title,
    priority,
    tags: Array.isArray(tags) ? tags : [tags],
    markdown: markdown
};

return [{ json: { url, headers, payload } }];

const resp = $input.first().json;
const statusCode = resp.statusCode || 0;
const body = resp.body || resp.data || {};

if (statusCode >= 200 && statusCode < 300) {
    return [{ json: { success: true, statusCode, id: body.id || '', message: '通知发送成功' } }];
} else {
    return [{ json: { success: false, statusCode, error: body.error || JSON.stringify(body), message: '通知发送失败' } }];
}
